        external
        view
        returns (Ticket[] memory list, TicketStatus[] memory displayStatuses)
    {
        uint256[] storage ids = _ticketsOf[owner_];
        list            = new Ticket[](ids.length);
        displayStatuses = new TicketStatus[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
