        if (_sink == address(0)) revert ZeroAddress();
        protocolSink = _sink;
        emit ProtocolSinkSet(_sink);
    }

    function setYieldVault(address _vault) external onlyOwner {
        yieldVault = _vault; // address(0) allowed = yield disabled
        emit YieldVaultSet(_vault);
    }

