        t.status = TicketStatus.Ineligible;
        _vaultRemove(ticketId);
        if (activeTicketOf[t.owner] == ticketId) activeTicketOf[t.owner] = 0;
        emit TicketIneligible(ticketId, t.escrowAmount, t.escrowToken);
